const role=()=>['admin','supervisor'].includes(P?.role),isAdmin=()=>P?.role==='admin',go=x=>location.hash=x,date=x=>x?new Date(x+'T12:00:00').toLocaleDateString():'—',dt=x=>x?new Date(x).toLocaleString():'—';
