async function crew(){if(!role()){q('#page').innerHTML='<div class="head"><div><div class="ey">Crew</div><h1>My Crew</h1></div></div><div class="empty">Crew management is available to supervisors and admins.</div>';return}let[pp,cc]=await Promise.all([S.from('profiles').select('*').order('active',{ascending:false}).order('full_name'),S.from('crews').select('id,name,created_by,active,created_at,crew_members(user_id,profiles(full_name,email,active))').eq('active',true).order('name')]);if(pp.error){q('#page').innerHTML=`<div class="msg">${e(pp.error.message)}</div>`;return}let p=pp.data||[],crews=cc.error?[]:(cc.data||[]);q('#page').innerHTML=`<div class="head"><div><div class="ey">Crew Management</div><h1>Saved Crews</h1><div class="sub">Build crews once, then select the whole crew when sending a Job Brief.</div></div><button class="btn primary" id="addCrew">+ New Crew</button></div><div class="list" style="margin-bottom:26px">${crews.map(c=>{let ms=(c.crew_members||[]).filter(m=>m.profiles?.active!==false);return`<div class="row" style="cursor:default"><div><b>${e(c.name)}</b><div class="meta">${ms.length} member${ms.length===1?'':'s'}${ms.length?' · '+ms.slice(0,4).map(m=>e(m.profiles?.full_name||m.profiles?.email||'Employee')).join(', ')+(ms.length>4?'…':''):''}</div></div><button class="btn outline small" data-edit-crew="${c.id}">Manage</button></div>`}).join('')||'<div class="empty">No saved crews yet. Create one so supervisors can assign a whole crew in one tap.</div>'}</div><div class="head" style="margin-top:6px"><div><div class="ey">People</div><h1 style="font-size:25px">EnerSite Employees</h1><div class="sub">Accounts available for Job Brief assignments.</div></div>${isAdmin()?'<button class="btn outline" id="addEmp">+ Add Employee</button>':''}</div><div class="card" style="padding:10px"><div class="people">${p.map(x=>`<div class="person"><div><b>${e(x.full_name||x.email)}</b><small>${e(x.email||'')} ${x.phone?'· '+e(x.phone):''}</small></div><span class="status ${x.active?'':'inactive'}">${x.active?e(x.role):'inactive'}</span>${isAdmin()&&x.id!==U.id?`<button class="btn outline small" data-manage="${x.id}" data-name="${e(x.full_name||x.email)}" data-role="${e(x.role)}" data-active="${x.active}">Manage</button>`:''}</div>`).join('')}</div></div>`;q('#addCrew').onclick=()=>showCrewEditor(null,p);q('#addEmp')&&(q('#addEmp').onclick=showAddEmployee);qa('[data-edit-crew]').forEach(b=>b.onclick=()=>showCrewEditor(crews.find(c=>c.id===b.dataset.editCrew),p));qa('[data-manage]').forEach(b=>b.onclick=()=>showManageEmployee(b.dataset.manage,b.dataset.name,b.dataset.role,b.dataset.active==='true'))}
function closeModal(){M.innerHTML=''}
async function refreshNotificationBadge(){
 if(!U)return;
 let{count,error}=await S.from('notifications').select('id',{count:'exact',head:true}).eq('user_id',U.id).is('read_at',null);
 if(error)return;
 let b=q('#notifBadge');if(!b)return;
 let n=count||0;b.textContent=n>99?'99+':String(n);b.style.display=n?'block':'none';
}
async function showNotifications(){
 let{data,error}=await S.from('notifications').select('id,brief_id,title,body,read_at,created_at').eq('user_id',U.id).order('created_at',{ascending:false}).limit(30);
 if(error)return toast(error.message);
 let rows=data||[],unread=rows.filter(x=>!x.read_at).length;
 M.innerHTML=`<div class="modalback"><div class="modal"><div class="modalhead"><div style="flex:1"><div class="ey">Inbox</div><h3 style="margin-top:3px">Notifications</h3></div>${unread?'<button class="btn outline small" id="markAllRead">Mark all read</button>':''}<button class="btn outline small" id="mx">Close</button></div><div class="divider"></div><div class="people">${rows.map(x=>`<button type="button" data-notif="${e(x.id)}" data-notif-brief="${e(x.brief_id||'')}" style="width:100%;text-align:left;border:1px solid ${x.read_at?'#ddd':'#f2a56d'};background:${x.read_at?'#fff':'#fff7f0'};border-radius:10px;padding:11px;cursor:pointer"><div style="display:flex;align-items:start;gap:8px"><div style="flex:1"><b>${e(x.title||'Job Brief')}</b><div class="meta" style="margin-top:4px">${e(x.body||'')}</div><div class="meta" style="margin-top:5px">${dt(x.created_at)}</div></div>${x.read_at?'':'<span class="status sent">New</span>'}</div></button>`).join('')||'<div class="empty">No notifications yet.</div>'}</div></div></div>`;
 q('#mx').onclick=closeModal;
 q('#markAllRead')&&(q('#markAllRead').onclick=async()=>{let{error}=await S.from('notifications').update({read_at:new Date().toISOString()}).eq('user_id',U.id).is('read_at',null);if(error)return toast(error.message);closeModal();refreshNotificationBadge();toast('Notifications marked read')});
 qa('[data-notif]').forEach(btn=>btn.onclick=async()=>{let{error}=await S.from('notifications').update({read_at:new Date().toISOString()}).eq('id',btn.dataset.notif).eq('user_id',U.id);if(error)return toast(error.message);let brief=btn.dataset.notifBrief;closeModal();refreshNotificationBadge();if(brief)go('brief/'+brief)});
}

function showAddEmployee(){M.innerHTML=`<div class="modalback"><div class="modal"><div class="modalhead"><h3>Add EnerSite Employee</h3><button class="btn outline small" id="mx">Close</button></div><div id="merr"></div><form id="empForm"><div class="f"><label>Full Name</label><input name="name" required></div><div class="f"><label>Email</label><input name="email" type="email" required></div><div class="f"><label>Phone</label><input name="phone"></div><div class="f"><label>Role</label><select name="role"><option value="employee">Employee</option><option value="supervisor">Supervisor</option><option value="admin">Admin</option></select></div><div class="f"><label>Temporary Password</label><input name="password" minlength="8" required placeholder="At least 8 characters"></div><div class="warn">This account is created immediately and does not require an email confirmation. Give the employee the email and temporary password securely.</div><button class="btn primary wide" style="margin-top:12px">Create Employee</button></form></div></div>`;q('#mx').onclick=closeModal;q('#empForm').onsubmit=async ev=>{ev.preventDefault();let f=new FormData(ev.target);let{data,error}=await S.functions.invoke('admin-users',{body:{action:'create',full_name:f.get('name'),email:f.get('email'),phone:f.get('phone'),role:f.get('role'),password:f.get('password')}});if(error||data?.error){q('#merr').innerHTML=`<div class="msg">${e(data?.error||error?.message||'Could not create employee')}</div>`;return}closeModal();toast('Employee created');crew()}}
function showManageEmployee(id,name,role0,active0){M.innerHTML=`<div class="modalback"><div class="modal"><div class="modalhead"><h3>Manage ${e(name)}</h3><button class="btn outline small" id="mx">Close</button></div><div id="merr"></div><div class="f"><label>Role</label><select id="mr"><option value="employee" ${role0==='employee'?'selected':''}>Employee</option><option value="supervisor" ${role0==='supervisor'?'selected':''}>Supervisor</option><option value="admin" ${role0==='admin'?'selected':''}>Admin</option></select></div><div class="f"><label>Status</label><select id="ma"><option value="true" ${active0?'selected':''}>Active</option><option value="false" ${!active0?'selected':''}>Inactive</option></select></div><button class="btn primary wide" id="ms">Save Employee</button><div class="divider"></div><div class="f"><label>Set New Password</label><input id="mp" type="password" minlength="8" placeholder="At least 8 characters"></div><button class="btn outline wide" id="mpr">Reset Password</button></div></div>`;q('#mx').onclick=closeModal;q('#ms').onclick=async()=>{let{data,error}=await S.functions.invoke('admin-users',{body:{action:'update_employee',user_id:id,role:q('#mr').value,active:q('#ma').value==='true'}});if(error||data?.error)return q('#merr').innerHTML=`<div class="msg">${e(data?.error||error?.message)}</div>`;closeModal();toast('Employee updated');crew()};q('#mpr').onclick=async()=>{let pw=q('#mp').value;if(pw.length<8)return q('#merr').innerHTML='<div class="msg">Password must be at least 8 characters.</div>';let{data,error}=await S.functions.invoke('admin-users',{body:{action:'reset_password',user_id:id,password:pw}});if(error||data?.error)return q('#merr').innerHTML=`<div class="msg">${e(data?.error||error?.message)}</div>`;toast('Password reset');closeModal()}}
async function showCrewEditor(c,p){let members=new Set((c?.crew_members||[]).map(m=>m.user_id)),active=(p||[]).filter(x=>x.active);M.innerHTML=`<div class="modalback"><div class="modal"><div class="modalhead"><h3>${c?'Manage':'Create'} Saved Crew</h3><button class="btn outline small" id="mx">Close</button></div><div id="merr"></div><div class="f"><label>Crew Name</label><input id="crewName" value="${e(c?.name||'')}" placeholder="Example: Crew 1"></div><div class="ey" style="margin:14px 0 7px">Members</div><div class="people">${active.map(x=>`<label class="personcheck"><input type="checkbox" data-cm="${x.id}" ${members.has(x.id)?'checked':''}><div><b>${e(x.full_name||x.email)}</b><div class="meta">${e(x.role)} · ${e(x.email||'')}</div></div></label>`).join('')}</div><button class="btn primary wide" style="margin-top:14px" id="saveCrew">${c?'Save Crew':'Create Crew'}</button>${c?'<button class="btn danger wide" style="margin-top:8px" id="deleteCrew">Delete Crew</button>':''}</div></div>`;q('#mx').onclick=closeModal;q('#saveCrew').onclick=async()=>{let name=q('#crewName').value.trim(),ids=qa('[data-cm]:checked').map(x=>x.dataset.cm);if(!name)return q('#merr').innerHTML='<div class="msg">Enter a crew name.</div>';if(!ids.length)return q('#merr').innerHTML='<div class="msg">Select at least one crew member.</div>';let id=c?.id;if(!id){let{data,error}=await S.from('crews').insert({name,created_by:U.id,active:true}).select('id').single();if(error)return q('#merr').innerHTML=`<div class="msg">${e(error.message)}</div>`;id=data.id}else{let{error}=await S.from('crews').update({name}).eq('id',id);if(error)return q('#merr').innerHTML=`<div class="msg">${e(error.message)}</div>`}let del=await S.from('crew_members').delete().eq('crew_id',id);if(del.error)return q('#merr').innerHTML=`<div class="msg">${e(del.error.message)}</div>`;let ins=await S.from('crew_members').insert(ids.map(user_id=>({crew_id:id,user_id})));if(ins.error)return q('#merr').innerHTML=`<div class="msg">${e(ins.error.message)}</div>`;closeModal();toast(c?'Crew updated':'Crew created');crew()};q('#deleteCrew')&&(q('#deleteCrew').onclick=async()=>{if(!confirm(`Delete ${c.name}?`))return;let d1=await S.from('crew_members').delete().eq('crew_id',c.id);if(d1.error)return q('#merr').innerHTML=`<div class="msg">${e(d1.error.message)}</div>`;let d2=await S.from('crews').delete().eq('id',c.id);if(d2.error)return q('#merr').innerHTML=`<div class="msg">${e(d2.error.message)}</div>`;closeModal();toast('Crew deleted');crew()})}

function scheduleLiveRefresh(){
 clearTimeout(liveRefreshTimer);
 liveRefreshTimer=setTimeout(async()=>{
  if(!U)return;
  let[h,id]=(location.hash.slice(1)||'home').split('/');
  refreshNotificationBadge();
  if(h==='home')home();
  else if(h==='briefs')briefs();
  else if(h==='brief'&&id)detail(id);
 },350);
}
function startLiveSync(){
 if(liveChannel){S.removeChannel(liveChannel);liveChannel=null}
 if(!U)return;
 liveChannel=S.channel('enersite-live-'+U.id)
  .on('postgres_changes',{event:'*',schema:'public',table:'job_briefs'},scheduleLiveRefresh)
  .on('postgres_changes',{event:'*',schema:'public',table:'job_brief_recipients'},scheduleLiveRefresh)
  .on('postgres_changes',{event:'*',schema:'public',table:'signatures'},scheduleLiveRefresh)
  .on('postgres_changes',{event:'*',schema:'public',table:'notifications',filter:`user_id=eq.${U.id}`},scheduleLiveRefresh)
  .on('postgres_changes',{event:'*',schema:'public',table:'audit_log'},scheduleLiveRefresh)
  .subscribe();
}

function profilePage(){q('#page').innerHTML=`<div class="head"><div><div class="ey">Account</div><h1>${e(P.full_name||'Profile')}</h1><div class="sub">${e(U.email||'')} · ${e(P.role)}</div></div></div><div class="card" style="padding:18px;max-width:620px"><div class="f"><label>Name</label><input value="${e(P.full_name||'')}" disabled></div><div class="f"><label>Phone</label><input value="${e(P.phone||'')}" disabled></div><div class="divider"></div><h3>Change Password</h3><div class="f"><label>New Password</label><input id="newPw" type="password" minlength="8"></div><button class="btn dark" id="cpw">Update Password</button><div class="divider"></div><button class="btn outline" id="out">Sign Out</button></div>`;q('#cpw').onclick=async()=>{let pw=q('#newPw').value;if(pw.length<8)return toast('Use at least 8 characters');let{error}=await S.auth.updateUser({password:pw});if(error)return toast(error.message);q('#newPw').value='';toast('Password updated')};q('#out').onclick=()=>S.auth.signOut()}
